import {inspectZip} from './intake-core.mjs';
import {taskNames,typeNames,criterionNames,statusNames,executionNames,inputKey,validateInput,checkAssessment,coverageCounts,sessionCapability,metricUnit,hasCode} from './online-core.mjs';

async function encoded(blob){const bytes=new Uint8Array(await blob.arrayBuffer());let s='';for(let n=0;n<bytes.length;n+=32768)s+=String.fromCharCode(...bytes.subarray(n,n+32768));return btoa(s);}
const uid=()=>crypto.randomUUID();

export class OnlineWorkspace{
 constructor(intake){this.i=intake;this.selected=null;this.tab='materials';this.token='';this.consent=false;this.errors={};this.error='';this.busy='';this.capabilities=null;this.timer=null;this.repoTimer=null;this.repoGeneration=0;this.repoPending=null;this.repoState='';this.pending=false;this.owner=null;try{this.owner=sessionCapability();}catch{this.error='浏览器存储不可用，暂时无法保存审查身份。请允许此网站使用本地存储。';}}
 esc(value){return this.i.esc(value??'');}
 current(){return this.i.projects.find(p=>p.id===this.selected)||null;}
 async new(){const p={id:uid(),title:'',created_at:new Date().toISOString(),paper:null,repository:null,claims:[],resources:{},online_task:'auto',online_scope:'',online_max_seconds:'',online_auto_execute:true};this.i.projects.unshift(p);this.selected=p.id;this.i.activeId=p.id;this.tab='materials';this.error='';this.errors={};await this.i.save(p);this.i.h.navigate('api-review');}
 ensure(){if(!this.current()){this.selected=this.i.projects[0]?.id;if(!this.selected)return null;}return this.current();}
 warn(key){return this.errors[key]?`<span class="online-field-error" role="alert">! ${this.esc(this.errors[key])}</span>`:'';}
 attrs(key){return this.errors[key]?'aria-invalid="true"':'';}
 render(){const p=this.ensure(),e=v=>this.esc(v);if(!p)return `<section class="online-empty"><h2>从一份材料开始</h2><p>上传论文、导入代码，或两者一起提交。</p><button class="btn primary" data-online="new">新建在线审查</button></section>`;
 const report=p.online_report,stale=report&&p.online_input_key!==inputKey(p);
 return `<div class="online-workspace"><div class="online-toolbar"><label for="online-project">当前项目</label><select id="online-project" data-online-project ${this.busy?'disabled':''}>${this.i.projects.map(x=>`<option value="${e(x.id)}" ${x.id===p.id?'selected':''}>${e(x.title||'新建审查')}</option>`).join('')}</select><button class="btn text" data-online="new" ${this.busy?'disabled':''}>新建审查</button><span class="online-service">${this.capabilities?this.capabilities.sandbox_configured?'模型与云端执行已配置':'模型审查可用 · 云端执行待配置':'材料保存在当前浏览器'}</span></div>
 <nav class="online-tabs" aria-label="审查工作区">${[['materials','提交材料'],['report','审查报告'],['execution','执行与日志'],['evidence','图表与证据'],['roles','角色记录']].map(([id,label])=>`<button data-online-tab="${id}" class="${this.tab===id?'selected':''}" aria-current="${this.tab===id?'page':'false'}">${label}</button>`).join('')}</nav>
 ${this.error?`<div class="online-error" role="alert"><strong>本次操作未完成</strong><p>${e(this.error)}</p></div>`:''}${stale?'<p class="online-notice">材料或审查范围已变化。下方保留旧版本报告，请重新审查当前版本。</p>':''}
 ${this.busy?`<div class="online-progress" role="status" aria-live="polite"><span class="online-spinner" aria-hidden="true"></span><div><strong>${e(this.busy)}</strong><p>仅展示服务实际状态，返回结果后自动更新。</p></div></div>`:''}
 ${this.tab==='materials'?this.materials(p):!report?.review?`<section class="online-empty"><h2>${report?.status==='reviewing'?'正在审查材料':report?.status==='failed'?'本次审查未完成':'还没有本次审查结果'}</h2><p>提交材料后，报告和执行证据会出现在这里。</p><button class="btn" data-online-tab="materials">准备材料</button></section>`:this.tab==='report'?this.report(report):this.tab==='execution'?this.execution(report,stale):this.tab==='roles'?this.roles(report):this.evidence(report)}
 </div>`;}
 materials(p){const e=v=>this.esc(v),report=p.online_report;
 return `<div class="online-intake-grid"><section class="online-form"><div class="online-section-heading"><h2>论文与代码</h2><span>至少提供一项</span></div>
 <div class="online-upload-pair"><label class="online-upload" for="online-pdf"><span>论文 PDF</span><strong>${e(p.paper?.name||'上传论文')}</strong><small>${p.paper?`${p.paper.pages?.length||0} 页 · 点击替换`:'用于图表指标、数据与论证自查'}</small><input id="online-pdf" type="file" accept=".pdf,application/pdf" data-online-upload="paper" ${this.busy?'disabled':''}></label>
 <label class="online-upload" for="online-zip"><span>代码 ZIP</span><strong>${e(p.repository?.name||'上传代码')}</strong><small>${p.repository?`${p.repository.files?.length||0} 个文件 · 点击替换`:'最大 100 MB，也可填写 GitHub 地址'}</small><input id="online-zip" type="file" accept=".zip,application/zip" data-online-upload="code" ${this.busy?'disabled':''}></label></div>${this.warn('material')}
 <div class="online-field"><label for="online-repo">公开 GitHub 仓库 <small>可选，填入后自动读取源码</small></label><div class="online-input-action"><input id="online-repo" type="url" data-online-field="repo_url" value="${e(p.repo_url||'')}" placeholder="https://github.com/作者/仓库" ${this.busy?'disabled':''}><button class="btn" data-online="github" ${this.busy?'disabled':''}>${this.repoState==='读取失败'?'重新读取':'读取'}</button></div><span class="online-repo-state" role="status">${e(this.repoState||p.repository?.commit&&'固定提交 '+p.repository.commit.slice(0,12)||'')}</span></div>
 <fieldset class="online-task"><legend>审查需求</legend>${Object.entries(taskNames).map(([id,label])=>`<label><input type="radio" name="online-task" value="${id}" data-online-field="online_task" ${id===(p.online_task||'auto')?'checked':''} ${this.busy?'disabled':''}><span>${label}</span></label>`).join('')}</fieldset>
 <p class="online-task-note">只传论文可查图表、数字与论证；只传代码可查实现与运行条件。</p>
 <div class="online-field"><label class="online-checkbox"><input type="checkbox" data-online-field="online_restrict" ${p.online_restrict?'checked':''} ${this.busy?'disabled':''}>只检查指定范围</label>${p.online_restrict?`<label class="sr-only" for="online-scope">本次审查范围</label><textarea id="online-scope" data-online-field="online_scope" ${this.attrs('scope')} placeholder="例如：Table 3 中 ResNet-110 的 CIFAR-10 错误率">${e(p.online_scope||'')}</textarea>${this.warn('scope')}`:'<small>默认检查材料中所有可识别、适用的图表指标；未覆盖项在报告中说明。</small>'}</div>
 <div class="online-options"><div class="online-field"><label for="online-seconds">最长执行时间 <small>可选</small></label><div class="online-time"><input id="online-seconds" type="number" min="30" max="600" data-online-field="online_max_seconds" value="${e(p.online_max_seconds||'')}" placeholder="默认 300" ${this.attrs('seconds')} ${this.busy?'disabled':''}><span>秒</span></div>${this.warn('seconds')}</div><label class="online-checkbox"><input type="checkbox" data-online-field="online_auto_execute" ${p.online_auto_execute!==false?'checked':''} ${this.busy?'disabled':''}>有适用计划时自动在云端 CPU 环境执行</label></div>
 <details class="online-local"><summary>在自己的电脑执行</summary><p>如需本地数据或 GPU，可使用本地工作台。在线审查不要求本地连接。</p><button class="btn text" data-online="local">打开本地项目配置</button></details>
 ${p.online_report?.execution?.needs_user||p.online_report?.availability?`<div class="online-field"><label for="online-supply">补充数据、权重或获取线索</label><textarea id="online-supply" data-online-field="online_supply_notes" maxlength="3000" placeholder="填写公开数据 / 权重地址或补充说明；文件可放入代码 ZIP。不要填写账号密码或密钥。">${e(p.online_supply_notes||'')}</textarea><small>补充后重新审查，原执行与材料版本保留在历史记录中。</small></div>`:''}<section class="online-access"><div class="online-field"><label for="online-token">网站访问码</label><input id="online-token" type="password" autocomplete="off" data-online-token placeholder="${this.token?'已填写，本页有效':'由管理员提供'}" ${this.attrs('token')} ${this.busy?'disabled':''}>${this.warn('token')}</div><label class="online-checkbox"><input type="checkbox" data-online-consent ${this.consent?'checked':''} ${this.busy?'disabled':''}>允许处理本次材料并发送相关内容至模型服务；大文件经临时隔离环境传输，执行开启时在云端运行代码。</label>${this.warn('consent')}<small>原始材料保存在浏览器；云端审查报告保留 7 天，可随时导出。</small><div class="online-submit"><button class="btn primary" data-online="submit" ${this.busy?'disabled':''}>${report?'重新审查当前材料':'开始自动审查'}</button>${report?'<button class="btn" data-online-tab="report">查看上次报告</button>':''}</div></section></section>
 <aside class="online-rail"><h2>本次审查</h2><dl><div><dt>论文</dt><dd>${p.paper?'已导入':'未提供'}</dd></div><div><dt>代码</dt><dd>${p.repository?.blob?'源码已导入':'未提供'}</dd></div><div><dt>范围</dt><dd>${p.online_restrict?'指定范围':'自动识别全部适用项'}</dd></div><div><dt>执行位置</dt><dd>${p.online_auto_execute!==false?'云端 CPU':'仅审查材料'}</dd></div></dl>${report?'<button class="btn" data-online-tab="report">继续查看报告</button>':''}<details><summary>材料缺失时会怎样？</summary><p>先完成能做的审查。自动获取或执行确实受阻时，再请你补充。</p></details></aside></div>`;}
 report(r){const e=v=>this.esc(v),v=r.review,c=coverageCounts(r);
 return `<section class="online-summary"><div><span class="online-kicker">${e(typeNames[v.paper_type])} · ${e(taskNames[v.task])}</span><h2>${r.execution?e(executionNames[r.execution.status]||r.execution.status)+' · '+(r.execution.stages?.filter(s=>s.status==='completed').length||0)+' 个阶段已执行':e(v.paper_type==='unknown'?'材料识别结果':v.paper_type==='nonpaper'?'材料适用性说明':taskNames[v.task]+'报告')}</h2><p>${e(r.execution?(v.paper_type==='code_only'?'本次审查代码实现、依赖与运行流程；论文结论对齐不属于本次范围。':v.classification_reason):v.summary)}</p>${r.execution?`<details class="online-review-origin"><summary>材料审查时的判断</summary><p>${e(v.summary)}</p></details>`:''}</div><button class="btn" data-online="export">导出报告</button></section>
 ${r.audit?`<p class="online-notice">${r.audit.status==='completed'?'交叉复核保留 '+v.findings.length+' 条建议，撤回 '+r.audit.withdrawn+' 条依据不足的建议，补充 '+r.audit.additional_metrics+' 条图表指标。':'本次交叉复核未完成，模型建议仍需人工核对。'}</p>`:''}<div class="online-counts"><div><span>识别图表指标</span><strong>${c.identified}<small> 项</small></strong></div><div><span>问题与建议</span><strong>${v.findings.length}<small> 项</small></strong></div><div><span>执行观测指标</span><strong>${c.observed}<small> / ${c.identified}</small></strong></div><div><span>覆盖缺口</span><strong>${c.gaps}<small> 项</small></strong></div></div>
 <section class="online-criteria"><div class="online-section-heading"><h2>${v.task==='self_review'?'论文自查条件':'八项审查条件'}</h2><span>材料依据与执行结论分开记录</span></div><div class="online-criteria-grid">${v.criteria.map(row=>`<details class="online-criterion ${e(row.status)}"><summary><strong>${e(criterionNames[row.dimension])}</strong><span class="online-status ${e(row.status)}">${e(statusNames[row.status])}</span></summary><p>${e(row.note)}</p>${this.citation(row)}</details>`).join('')}</div></section>
 <section class="online-findings"><div class="online-section-heading"><h2>问题与修正建议</h2><span>${v.findings.length} 项</span></div>${v.findings.map((f,n)=>`<article><header><span class="online-issue-index">${String(n+1).padStart(2,'0')}</span><h3>${e(f.title)}</h3><span class="online-severity ${e(f.severity)}">${e({high:'优先处理',medium:'建议核对',low:'补充说明'}[f.severity])}</span></header><p>${e(f.detail)}</p><div class="online-suggestion"><strong>修正建议</strong><p>${e(f.suggestion)}</p></div>${f.audit_note?`<p class="online-audit-note"><strong>交叉复核</strong> ${e(f.audit_note)}</p>`:''}${this.citation(f)}</article>`).join('')||'<p class="online-notice">本次审查未列出问题建议，不等于论文结论已验证。</p>'}</section>
 ${r.audit?.withdrawn?`<details class="online-withdrawn"><summary>查看撤回的 ${r.audit.withdrawn} 条原建议</summary>${r.audit.reviews.filter(x=>x.decision==='remove').map(x=>`<article><h3>${e(r.audit.raw_findings[x.index].title)}</h3><p>${e(x.reason)}</p></article>`).join('')}</details>`:''}${r.execution?`<button class="btn" data-online-tab="execution">${e(executionNames[r.execution.status]||r.execution.status)} · 查看实际日志</button>`:`<div class="online-notice"><strong>执行计划</strong><p>${e(v.plan.purpose||v.plan.blocked_reason||'当前任务以材料审查为主。')}</p><button class="btn text" data-online-tab="execution">查看计划与执行条件</button></div>`}`;}
 citation(row){return row.page||row.file?`<small class="online-citation">${row.page?'PDF 第 '+this.esc(row.page)+' 页':''}${row.page&&row.file?' · ':''}${this.esc(row.file||'')}</small>`:'';}
 execution(r,stale){const e=v=>this.esc(v),x=r.execution,p=r.review.plan;
 return `<section class="online-summary"><div><span class="online-kicker">隔离云端 CPU · 最长 ${e(p.max_seconds)} 秒</span><h2>${x?e(executionNames[x.status]||x.status):'执行计划'}</h2><p>${e(p.purpose||p.blocked_reason||'当前没有适用的执行计划。')}</p></div><div class="source-actions">${!x&&p.stages.length?`<button class="btn primary" data-online="execute" ${stale||this.busy?'disabled':''}>执行本次计划</button>`:''}${['running','cancelling'].includes(x?.status)?'<button class="btn" data-online="refresh">刷新状态</button><button class="btn" data-online="cancel">停止执行</button>':''}${x?.attempt_id&&['failed','expired','cancelled'].includes(x.status)&&(r.execution_history?.length||0)<2?`<button class="btn" data-online="retry" ${stale||this.busy?'disabled':''}>重试执行</button>`:''}<button class="btn" data-online="export">导出报告</button></div></section>${x?.notice?`<p class="online-notice">${e(x.notice)}</p>`:''}${!p.stages.length?`<p class="online-notice">${e(p.blocked_reason||'材料不足以生成真实执行计划。可以先查看已完成的材料审查。')}</p>`:''}
 <div class="online-stage-list">${p.stages.map((s,n)=>{const a=x?.stages?.find(z=>z.id===s.id),state=a?.status||'planned';return `<details class="online-stage" ${state==='failed'||state==='running'?'open':''}><summary><span class="online-issue-index">${n+1}</span><strong>${e(s.title)}</strong><span class="online-status ${state==='failed'?'missing':state==='completed'?'documented':'needs_review'}">${e({planned:'计划中',running:'执行中',completed:'已执行',failed:'执行失败',skipped:'已跳过'}[state]||state)}</span></summary><p class="online-citation">来源 ${e(s.file)}${a?.exit_code!=null?' · 退出码 '+e(a.exit_code):''}</p><pre>${e(s.command)}</pre>${a?.output?`<h3>实际输出</h3><pre class="online-output">${e(a.output)}</pre>${a.output_truncated?'<small>输出已截断，未显示部分不参与当前指标提取。</small>':''}`:''}${a?.reason?`<p>${e(a.reason)}</p>`:''}</details>`;}).join('')}</div>
 ${!x&&r.review.resource_preflight?.needs_user?`<section class="online-blocker"><h3>当前云端计算条件不足</h3><p>${e(r.review.resource_preflight.reason)}</p><p>服务提供 2 vCPU、512 MB 内存，无 GPU；需求来自材料分析，本次未启动实验。</p>${r.availability?`<strong>${e(r.availability.verdict)}</strong>`:'<button class="btn" data-online="can-provide">可提供所需资源</button><button class="btn" data-online="unavailable">确认无法提供</button>'}<button class="btn text" data-online="local">使用本地环境</button></section>`:''}${!x&&r.review.task==='reproduction'&&!r.materials.code?`<section class="online-blocker"><h3>需要补充代码来源</h3><p>${e(r.source_discovery?.reason||'自动分析未能取得可执行源码，请补充 GitHub 地址或代码 ZIP。')}</p>${r.availability?`<strong>${e(r.availability.verdict)}</strong><button class="btn" data-online-tab="materials">补充材料</button>`:'<button class="btn" data-online="can-provide">可以补充</button><button class="btn" data-online="unavailable">确认无法获取</button>'}</section>`:''}${x?.needs_user?`<section class="online-blocker"><h3>需要补充材料</h3><p>${e(x.question)}</p>${x.user_answer?`<strong>${e(x.availability_verdict)}</strong>${x.user_answer==='can_provide'?'<button class="btn" data-online-tab="materials">补充材料</button>':''}`:'<button class="btn" data-online="can-provide">可以补充</button><button class="btn" data-online="unavailable">确认无法提供</button>'}</section>`:''}
 ${x?.metrics?.length?`<section><h2>本次指标观测</h2><div class="online-table-wrap"><table class="online-table"><thead><tr><th>指标</th><th>论文值</th><th>观测值</th><th>比较结果</th></tr></thead><tbody>${x.metrics.map(m=>`<tr><td>${e(m.metric)}</td><td class="number">${e(m.expected)} ${e(m.unit)}</td><td class="number">${m.observed==null?'未观测':e(m.observed)}</td><td>${e({unobserved:'无可比较输出',within_tolerance:'数值在容差内',outside_tolerance:'超出容差'}[m.status])}</td></tr>`).join('')}</tbody></table></div></section>`:''}
 ${x?.environment?`<p class="online-footnote">实际实例：${e(x.environment.cpu_count)} vCPU · ${e(x.environment.memory_mb)} MB 内存 · ${e(x.environment.template_id)}${x.runtime?' · Python '+e(x.runtime.python):''}${x.elapsed_seconds!=null?' · 执行 '+e(x.elapsed_seconds)+' 秒':''}</p>`:''}<p class="online-footnote">日志和数值来自本次代码执行。进程成功、数值吻合与论文主要结论成立分别判断；本页不自动将主要结论标记为通过。</p>`;}
 evidence(r){
  const e=v=>this.esc(v),v=r.review;
  return `<div class="online-section-heading"><h2>图表指标与出处</h2><span>作者方法优先 · ${v.metrics.length} 项</span></div>
   ${v.metrics.length?`<div class="online-table-wrap"><table class="online-table"><thead><tr><th>图表 / 模型</th><th>数据集与指标</th><th>报告值</th><th>出处</th></tr></thead><tbody>${v.metrics.map(m=>`<tr><td><strong>${e(m.reference)}</strong><span>${e(m.model)}${m.author_method?' · 作者方法':''}</span></td><td><strong>${e(m.dataset)}</strong><span>${e(m.metric)}</span></td><td class="number">${e(m.value)} ${e(metricUnit(m))}</td><td><details><summary>第 ${m.page} 页 · 查看原文</summary><blockquote>${e(m.quote)}</blockquote><p>${e(m.protocol)}</p><small>${m.evidence_kind==='image_reading'?'来自页面图像识别，建议对照原图核对':'已与该页提取文字对应'}</small><button class="btn text" data-online-page="${m.page}">打开 PDF 原页</button></details></td></tr>`).join('')}</tbody></table></div>`:'<p class="online-notice">没有通过出处核验的图表数字。正文中的零散数字未转换为实验指标。</p>'}
   ${v.visual_observations?.length?`<section class="online-coverage"><h2>曲线观察</h2><p>下列内容来自图像估读，用于定位，不作为精确数值验收目标。</p>${v.visual_observations.map(o=>`<article class="online-notice"><strong>${e(o.reference)} · 第 ${o.page} 页</strong><p>${e(o.note)}</p><button class="btn text" data-online-page="${o.page}">对照原图</button></article>`).join('')}</section>`:''}
   <section class="online-coverage"><h2>公开资料核对</h2><p>${e({completed:r.source_lookup?.cached?'已读取缓存的公开来源':'已检索公开来源',no_results:'未找到可用的公开来源',failed:'本次公开检索未完成',not_requested:'本次依据已提供材料开展内部核对'}[r.source_lookup?.status]||'本次未调用公开检索')}</p>
    ${(v.web_checks||[]).map(c=>`<article class="online-notice"><strong>${e(c.claim)}</strong><p>${e({supported:'有对应依据',contradicted:'发现不一致',unresolved:'证据不足'}[c.status])} · ${e(c.note)}</p><a href="${e(c.url)}" target="_blank" rel="noreferrer">查看引用来源</a></article>`).join('')}
    ${r.web_sources?.length?`<ul>${r.web_sources.map(source=>`<li><a href="${e(source.url)}" target="_blank" rel="noreferrer">${e(source.title||source.url)}</a></li>`).join('')}</ul>`:''}
   </section>
   <section class="online-coverage"><h2>覆盖边界</h2><p>${e(v.coverage.note)}</p><ul>${v.coverage.gaps.map(g=>`<li>${e(g)}</li>`).join('')||'<li>模型未列出额外缺口。仍以实际提供的页面和代码片段为审查范围。</li>'}</ul><p class="online-footnote">提供上下文：${e(v.coverage.paper_pages_in_context)} 页论文文字、${e(v.coverage.paper_images_in_context||0)} 张原页图像、${e(v.coverage.code_files_in_context)} / ${e(v.coverage.total_code_files)} 个代码文件。</p></section>`;
 }
 roles(r){const e=v=>this.esc(v),events=r.execution?.events||[],roles=[['literature_reader','文献审阅','模型 API 识别材料类型、图表和引用。'],['code_inspector','代码检查','模型 API 阅读提供的源文件和依赖。'],['planner','计划编排','模型 API 生成计划；执行器按冻结计划排程。'],['experiment_runner','实验执行','隔离 CPU 环境运行实际命令。'],['cross_auditor','交叉核查','校验出处、阶段退出码和数值比较。'],['reporter','报告整理','汇总审查建议、执行状态与覆盖缺口。']];return `<section class="online-roles"><h2>六角色职责与记录</h2><p class="online-footnote">文献与代码审查由同一次模型请求处理；角色名称表示工作流职责。</p>${roles.map(([id,name,note])=>{const rows=events.filter(v=>v.role===id);return `<details><summary><strong>${name}</strong><span>${rows.length?rows.length+' 条执行事件':id==='literature_reader'&&!r.materials.paper?'未提供论文':id==='code_inspector'&&!r.materials.code?'未提供代码':id==='literature_reader'||id==='code_inspector'?'模型审查已返回':id==='planner'&&r.review.plan.stages.length?'已生成计划':'尚无执行事件'}</span></summary><p>${note}</p>${rows.map(row=>`<div class="online-role-event"><code>${e(row.kind)}</code><span>${e(row.stage||row.status||row.reason||row.policy||'')}</span></div>`).join('')}</details>`;}).join('')}${events.length?`<section class="online-role-stream"><h3>最近执行事件</h3>${events.slice(-6).map(row=>`<div class="online-role-event"><span>${e({planner:'计划编排',experiment_runner:'实验执行',cross_auditor:'交叉核查',reporter:'报告整理'}[row.role]||row.role)}</span><strong>${e({plan_scheduled:'按冻结计划排程',stage_started:'开始执行',stage_finished:'执行结束',stage_checked:'核对阶段结果',execution_checked:'汇总执行证据',report_written:'写入报告',stopped:'结束排程'}[row.kind]||row.kind)}</strong><span>${e(r.review.plan.stages.find(s=>s.id===row.stage)?.title||row.status||row.reason||'')}</span></div>`).join('')}</section>`:''}</section>`;}
 async request(path,payload){if(!this.owner)throw Error('浏览器存储不可用，无法提交。');const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),115000);try{const response=await fetch('/v1'+path,{method:payload===undefined?'GET':'POST',headers:{'X-ArtiCheck-Client':'review-api','X-ArtiCheck-Session':this.owner,...(this.token?{Authorization:'Bearer '+this.token}:{}),...(payload===undefined?{}:{'Content-Type':'application/json'})},body:payload===undefined?undefined:JSON.stringify(payload),signal:controller.signal,credentials:'omit',redirect:'error'});let value;try{value=await response.json();}catch{throw Error('服务暂时没有返回有效响应，请稍后重试。');}if(!response.ok){const error=Error(value.error?.message||'请求失败。');error.code=value.error?.code;throw error;}return value;}catch(err){if(err.name==='AbortError')throw Error('等待服务返回超时，请刷新已有任务；不要连续重复提交。');throw err;}finally{clearTimeout(timer);}}
 async payload(p){
  const body={task:p.online_task||'auto',scope:p.online_restrict?p.online_scope:'',max_seconds:p.online_max_seconds?Number(p.online_max_seconds):null,supplement:p.online_supply_notes||''};
  const files=[['paper',p.paper],['code',p.repository]].filter(([,m])=>m?.blob);
  if(p.repository?.remote)body.code=p.repository.remote;
  if(files.reduce((n,[,m])=>n+m.blob.size,0)>3_000_000){
   const key=JSON.stringify(files.map(([kind,m])=>[kind,m.sha256,m.name,m.blob.size]));
   let transfer=p.online_upload;
   if(!transfer||transfer.key!==key||transfer.expires_at*1000<Date.now()+180000){
    if(!p.online_upload_pending||p.online_upload_pending.key!==key)p.online_upload_pending={key,id:uid().replaceAll('-','')};
    await this.save(p);
    const previous=this.busy;this.busy='正在建立大文件传输通道…';this.renderNow();
    try{
     const value=await this.request('/uploads',{request_id:p.online_upload_pending.id,files:files.map(([kind,m])=>({kind,name:m.name,bytes:m.blob.size,sha256:m.sha256}))});
     for(const [kind,m] of files){
      this.busy='正在传输 '+m.name+' · '+(m.blob.size/1024/1024).toFixed(1)+' MB';this.renderNow();
      const target=new URL(value.files[kind].upload_url);
      if(target.protocol!=='https:'||!['.e2b.app','.e2b.dev'].some(suffix=>target.hostname.endsWith(suffix)))throw Error('大文件传输地址无效。');
      const form=new FormData();form.append('file',m.blob,m.name);
      const response=await fetch(target.href,{method:'POST',body:form,credentials:'omit',redirect:'error',signal:AbortSignal.timeout(Math.max(1000,value.expires_at*1000-Date.now()-10000))});
      if(!response.ok)throw Error('大文件传输未完成，请重新提交；文件仍保存在当前浏览器。');
     }
     transfer={key,id:value.id,expires_at:value.expires_at,materials:Object.fromEntries(Object.entries(value.files).map(([kind,item])=>[kind,item.material]))};
     p.online_upload=transfer;p.online_upload_pending=null;await this.save(p);
    }finally{this.busy=previous;this.renderNow();}
   }
   Object.assign(body,transfer.materials);
  }else for(const [kind,m] of files)body[kind]={name:m.name,content_base64:await encoded(m.blob)};
  if(new TextEncoder().encode(JSON.stringify(body)).length>5_000_000)throw Error('材料描述过大，请缩短补充说明后重新提交。');
  return body;
 }
 async save(p){await this.i.save(p);}
 renderNow(){this.i.h.render();}
 async upload(kind,file){if(this.busy)return;const p=this.current();this.i.activeId=p.id;this.busy=kind==='paper'?'正在解析论文…':'正在读取代码…';this.renderNow();try{await this.i.upload(kind,file);if(this.i.error)throw Error(this.i.error);p.claims=[];if(!p.title)p.title=file.name.replace(/\.(pdf|zip)$/i,'');if(!p.online_task)p.online_task='auto';this.errors={};if(kind==='paper'&&!hasCode(p)&&!p.repo_url){const links=[...new Set((p.paper?.pages||[]).flatMap(v=>v.links||[]).map(u=>u.replace(/^http:/,'https:')).filter(u=>/^https:\/\/github\.com\/[\w.-]+\/[\w.-]+\/?$/.test(u)))];if(links.length===1){p.repo_url=links[0];this.repoState='从论文发现代码链接';}}await this.save(p);}catch(err){this.error=err.message;}finally{this.busy='';this.renderNow();if(kind==='paper'&&p.repo_url&&!hasCode(p)&&this.token)this.github();}}
 async github(force=false,internal=false){const p=this.current(),url=p?.repo_url?.trim();if(!url)return;if(!/^https:\/\/github\.com\/[\w.-]+\/[\w.-]+(?:\.git)?\/?(?:\?[^#]*)?$/.test(url)){this.error='请填写 GitHub 仓库首页地址。';this.renderNow();return;}if(!force&&hasCode(p)&&p.repository.url===url){this.repoState='已读取固定提交 '+p.repository.commit?.slice(0,12);return;}if(!this.token){this.repoState='填写网站访问码后自动读取';this.renderNow();return;}if(this.repoPending?.url===url)return this.repoPending.promise;if(this.busy&&!internal)return;const generation=++this.repoGeneration;this.repoState='正在读取源码…';this.error='';this.renderNow();const promise=(async()=>{try{const value=await this.request('/repositories',{url,refresh:force,...(internal?{assessment_id:p.online_report.id}:{})});if(generation!==this.repoGeneration||p!==this.current()||url!==p.repo_url.trim())return;if(value.assessment)p.online_report=checkAssessment(value.assessment);let source;if(value.material.content_base64){const bytes=Uint8Array.from(atob(value.material.content_base64),c=>c.charCodeAt(0));source={...inspectZip(bytes.buffer),blob:new Blob([bytes],{type:'application/zip'}),size:bytes.byteLength};}else source={remote:value.material,files:value.files,size:value.material.bytes};p.repository={...source,kind:'github',url:value.url,commit:value.commit,name:value.material.name,sha256:value.sha256,fetched_at:value.fetched_at,cached_reference:value.cached_reference};p.claims=[];if(!p.title)p.title=value.name;this.repoState=`源码已读取 · ${value.commit.slice(0,12)}`;await this.save(p);}catch(err){if(generation===this.repoGeneration){this.repoState='读取失败';this.error=err.message;}}finally{if(generation===this.repoGeneration){this.repoPending=null;this.renderNow();}}})();this.repoPending={url,promise};return promise;}
 async execute(p,{retry=false}={}){const r=p.online_report;if(!r?.review)throw Error('请先等待材料审查完成。');if(p.online_input_key!==inputKey(p))throw Error('材料或范围已变化，请重新审查。');if(!hasCode(p))throw Error('请补充代码源码。');this.busy='正在创建云端执行环境…';this.renderNow();const body=await this.payload(p);const value=checkAssessment(await this.request('/assessments/'+r.id+'/execute',{code:body.code,plan_sha256:r.review.plan_sha256,...(retry?{retry_of:r.execution.attempt_id}:{})}));p.online_report=value;await this.save(p);this.tab='execution';}
 async reviewOnce(p){
  const key=inputKey(p);
  if(!p.online_pending_request||p.online_pending_request.key!==key)p.online_pending_request={key,id:uid().replaceAll('-','')};
  await this.save(p);
  const value=checkAssessment(await this.request('/assessments',{...await this.payload(p),request_id:p.online_pending_request.id}));
  if(p.online_report?.id&&p.online_report.id!==value.id)p.online_history=[...(p.online_history||[]),{report:p.online_report,input_key:p.online_input_key}].slice(-20);
  p.online_report=value;p.online_input_key=key;
  if(value.status==='completed')p.online_pending_request=null;
  await this.save(p);
  return value;
 }
 async action(action){
  if(this.busy)return;
  const p=this.current();
  if(action==='new')return this.new();
  if(action==='export'){this.i.h.download('articheck-'+p.online_report.id+'.json',JSON.stringify(p.online_report,null,2));return;}
  if(action==='local'){this.i.activeId=p.id;return this.i.open(p.id,'readiness');}
  if(action==='github')return this.github(true);
  this.error='';
  try{
   if(action==='submit'){
    if(this.repoPending)await this.repoPending.promise;
    this.errors=validateInput(p,{token:this.token,consent:this.consent});
    if(Object.keys(this.errors).length){
     this.renderNow();
     const invalid=this.errors.material?document.querySelector('#online-pdf'):document.querySelector('[aria-invalid="true"]')||document.querySelector('[data-online-consent]');
     invalid?.focus();invalid?.scrollIntoView({block:'center',behavior:'smooth'});return;
    }
    this.busy='正在识别材料、阅读图表并核对公开资料…';this.renderNow();
    let value=await this.reviewOnce(p);
    if(value.review?.task==='reproduction'&&value.review.repository_hint&&!hasCode(p)){
     p.repo_url=value.review.repository_hint;
     this.busy='已找到代码来源线索，正在自动获取源码…';this.renderNow();
     await this.github(false,true);
     if(hasCode(p)){
      this.busy='正在结合代码补充审查与执行计划…';this.renderNow();
      value=await this.reviewOnce(p);
     }
    }
    this.consent=false;this.tab='report';
    if(p.online_auto_execute!==false&&value.review?.plan.stages.length)await this.execute(p);
   }else if(action==='execute'||action==='retry')await this.execute(p,{retry:action==='retry'});
   else if(['refresh','cancel','can-provide','unavailable'].includes(action)){
    this.busy=action==='cancel'?'正在停止执行…':'正在读取任务状态…';this.renderNow();
    const suffix=action==='refresh'?'':action==='cancel'?'/cancel':'/feedback';
    const payload=action==='refresh'?undefined:action==='cancel'?{}:{answer:action==='unavailable'?'unavailable':'can_provide'};
    p.online_report=checkAssessment(await this.request('/assessments/'+(p.online_report?.id||p.online_pending_request?.id)+suffix,payload));
    if(p.online_pending_request?.id===p.online_report.id){p.online_input_key=p.online_pending_request.key;if(p.online_report.status!=='reviewing')p.online_pending_request=null;}
    await this.save(p);
   }
  }catch(err){
   this.error=err.message;
   if(['upload_expired','upload_unavailable','upload_start_failed'].includes(err.code)){p.online_upload=null;p.online_upload_pending=null;await this.save(p);}
   if(action==='submit'&&p.online_pending_request){
    try{
     p.online_report=checkAssessment(await this.request('/assessments/'+p.online_pending_request.id));await this.save(p);
     if(p.online_report.status==='reviewing'){this.error='';this.tab='report';}
     else if(p.online_report.status==='failed')p.online_pending_request=null;
    }catch{}
   }
  }finally{this.busy='';this.renderNow();}
 }
 afterRender(){clearTimeout(this.timer);if(this.i.h.page()!=='api-review')return;if(!this.capabilities&&!this.pending){this.pending=true;this.request('/capabilities').then(v=>{this.capabilities=v;this.renderNow();}).catch(()=>{}).finally(()=>{this.pending=false;});}const p=this.current();if((['running','starting'].includes(p?.online_report?.execution?.status)||p?.online_report?.status==='reviewing'||p?.online_pending_request&&!p?.online_report)&&!this.busy&&this.token&&!this.error)this.timer=setTimeout(()=>this.action('refresh'),3000);}
 bind(){document.addEventListener('click',event=>{const source=event.target.closest('[data-online-page]');if(source){const p=this.current();if(!p.paper?.blob||p.paper.sha256!==p.online_report?.materials.paper){this.error='原 PDF 已变更或不在当前浏览器，请导入对应版本后查看。';this.renderNow();return;}const url=URL.createObjectURL(p.paper.blob);window.open(url+'#page='+Number(source.dataset.onlinePage),'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000);return;}const tab=event.target.closest('[data-online-tab]');if(tab){this.tab=tab.dataset.onlineTab;this.renderNow();return;}const action=event.target.closest('[data-online]');if(action)this.action(action.dataset.online);});document.addEventListener('change',event=>{const t=event.target;if(t.matches('[data-online-upload]')&&t.files[0])this.upload(t.dataset.onlineUpload,t.files[0]);if(t.matches('[data-online-project]')){this.selected=t.value;this.repoGeneration++;this.error='';this.errors={};this.repoState='';this.consent=false;this.renderNow();}if(t.matches('[data-online-consent]'))this.consent=t.checked;if(t.matches('[data-online-field]')){const p=this.current(),key=t.dataset.onlineField;p[key]=t.type==='checkbox'?t.checked:t.value;if(key==='online_restrict'){if(!p[key])p.online_scope='';this.renderNow();}this.save(p);}});document.addEventListener('input',event=>{const t=event.target;if(t.matches('[data-online-token]')){this.token=t.value;clearTimeout(this.repoTimer);if(this.current()?.repo_url)this.repoTimer=setTimeout(()=>this.github(),1800);}if(t.matches('[data-online-field]')){const p=this.current(),key=t.dataset.onlineField;if(t.type!=='radio'&&t.type!=='checkbox')p[key]=t.value;if(key==='repo_url'){if(p.repository?.kind==='github'&&p.repository.url!==t.value.trim())p.repository=null;this.repoGeneration++;clearTimeout(this.repoTimer);this.repoTimer=setTimeout(()=>this.github(),1800);}clearTimeout(this.inputSave);this.inputSave=setTimeout(()=>this.save(p),250);}});}
}
